document.addEventListener("click",e=>{const t=e.target.closest("[data-toggle-modal]");if(!t)return;const d=t.getAttribute("data-toggle-modal"),o=document.getElementById(d);if(o){const a=o.getAttribute("active")===String(!0);o.setAttribute("active",!a)}});const l=document.querySelectorAll("[data-modal-move]");l.forEach(e=>{const t=document.getElementById("modal-holder");t&&t.appendChild(e)});
